// Canvas Runner Game
// Assumes an HTML canvas element with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas with id "game" not found');
  const ctx = canvas.getContext('2d');
  const WIDTH = canvas.width = canvas.clientWidth || 800;
  const HEIGHT = canvas.height = canvas.clientHeight || 200;

  // Game parameters
  let speed = 2; // pixels per frame
  const GRAVITY = 0.5;
  const JUMP_STRENGTH = -10;
  const PLAYER_SIZE = 20;
  const GROUND_Y = HEIGHT - PLAYER_SIZE;

  const player = {
    x: 50,
    y: GROUND_Y,
    vy: 0,
    width: PLAYER_SIZE,
    height: PLAYER_SIZE,
    jump() {
      if (this.onGround()) this.vy = JUMP_STRENGTH;
    },
    onGround() {
      return this.y >= GROUND_Y;
    },
    update() {
      this.vy += GRAVITY;
      this.y += this.vy;
      if (this.y > GROUND_Y) {
        this.y = GROUND_Y;
        this.vy = 0;
      }
    },
    draw() {
      ctx.fillStyle = '#0f0';
      ctx.fillRect(this.x, this.y, this.width, this.height);
    }
  };

  const obstacles = [];
  let framesSinceLast = 0;
  const OBSTACLE_SPACING = 150; // frames between obstacles

  function spawnObstacle() {
    const size = 20 + Math.random() * 30; // variable height
    obstacles.push({
      x: WIDTH,
      y: GROUND_Y + PLAYER_SIZE - size, // align bottom
      width: size,
      height: size
    });
  }

  function updateObstacles() {
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= speed;
      if (o.x + o.width < 0) obstacles.splice(i, 1);
    }
    // spawn new obstacles
    framesSinceLast++;
    if (framesSinceLast > OBSTACLE_SPACING) {
      spawnObstacle();
      framesSinceLast = 0;
    }
  }

  function drawObstacles() {
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.width, o.height));
  }

  function checkCollision() {
    for (const o of obstacles) {
      if (
        player.x < o.x + o.width &&
        player.x + player.width > o.x &&
        player.y < o.y + o.height &&
        player.y + player.height > o.y
      ) {
        return true;
      }
    }
    return false;
  }

  let gameOver = false;
  function loop() {
    if (gameOver) return;
    ctx.clearRect(0, 0, WIDTH, HEIGHT);
    player.update();
    player.draw();
    updateObstacles();
    drawObstacles();
    if (checkCollision()) {
      gameOver = true;
      ctx.fillStyle = '#000';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', WIDTH / 2 - 80, HEIGHT / 2);
      return;
    }
    // gradually increase speed
    speed *= 1.0005;
    requestAnimationFrame(loop);
  }

  // Input handling (spacebar or click/tap)
  window.addEventListener('keydown', e => {
    if (e.code === 'Space') player.jump();
  });
  canvas.addEventListener('mousedown', () => player.jump());

  // Start the game loop
  loop();
})();
